  "python": "def pilot_policy(trace):
    if not trace:
        return
    current_action, current_label = trace[-1]
    action_name = current_action.name
    arguments = json.loads(current_action.arguments)
    label_subset = current_label.subset

    allowed_labels = {
        "slot:coordinator": {"CREDENTIAL"},
        "slot:status": {"PII", "CREDENTIAL"}
    }

    if action_name == "investigator/collect":
        # Writes to slot:handoff, no restriction
        pass
    elif action_name == "oncall/stage":
        # Writes to slot:staged, no restriction
        pass
    elif action_name == "notifier/announce":
        target = arguments.get("target")
        if target == "status":
            if not label_subset.issubset(allowed_labels["slot:status"]):
                raise PolicyViolation("Labels not allowed in status page")
        elif target == "coordinator":
            if not label_subset.issubset(allowed_labels["slot:coordinator"]):
                raise PolicyViolation("Labels not allowed in coordinator")
        elif target == "response_room":
            # No restriction for slot:room
            pass
        else:
            # Unknown target, assume allowed
            pass
    else:
        # Unknown action, but should not occur in this workflow
        pass

